import React from 'react'
import PropTypes from 'prop-types'
import EditPackageStyleWrapper from './index.style'
import { Row, Col, Form, Button, Spin, notification } from 'antd'
import CollapseWrapper from '../../components/PacakageComponent'
import { connect } from 'react-redux'
import { errorSectionCheck } from '../../../../../constants/payloadWrapper'
import { packagePayloadFormation, setFormFieldsDataFunction, payloadFormationFunction } from '../commanFunctions'
import { removeLocalStorage } from '../../../../../util/localstorageCheck'
import PageHeadWrapper from '../../../../../components/pageHeadWrapper'
import moment from 'moment'
import {
  get
  // , size
} from 'lodash'
import editPackageActions from '../../../../../../../redux/productConfig/actions'
import policyActions from '../../../../../../../../redux/policy/actions'
import QuerySearchBuilder from '../../../../../../../../helpers/querySearchBuilder'

const {
  resetProductConfigRedux,
  editPackage
} = editPackageActions
class EditPackage extends React.Component {
  state = {
    currentPanelState: [1, 2, 3, 4, 5, 6],
    nextButtonEnabled: true,
    packageData: {},
    step1Data: {},
    step2Data: []
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      editPackageData,
      editPackageMessage
    } = nextProps
    if (editPackageMessage === 'success') {
      const productCode = get(this.state.step1Data, 'code', '')
      const packageCode = get(this.state.packageData, 'code', '')
      notification.success(
        { message: get(editPackageData, 'message') }
      )
      this.props.resetProductConfigRedux(['editPackageMessage'])
      const queryString = QuerySearchBuilder({ product_code: productCode })

      this.props.history.push({
        pathname: '/product-config/detail',
        search: queryString,
        state: {
          code: productCode,
          visible: '1',
          packageCode: packageCode
        }
      })
    }
    if (editPackageMessage !== 'success' && editPackageMessage !== undefined) {
      const { message, errors } = get(editPackageMessage, 'data', {})
      if (Array.isArray(errors)) {
        errors.map((item) => {
          return (
            notification.error(
              {
                message: message,
                description: get(item, 'description', '')
              }
            )
          )
        })
      } else {
        notification.error(
          { message: message || 'Fail to Edit Package!!!' }
        )
      }
      this.props.resetProductConfigRedux(['editPackageMessage'])
    }
  }

  componentDidMount () {
    const { location } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'modal-page-edit':
      case 'detail-page-edit': {
        const packageData = packagePayloadFormation(get(location, 'state.formData.packageData', {}))
        const step1Data = get(location, 'state.formData.step1Data', {})
        const step2Data = get(location, 'state.formData.step2Data', {})
        this.setState({
          packageData,
          step1Data,
          step2Data
        })
      }
        break
      default: {
        this.props.history.goBack()
      }
    }
  }

  handleChangePanel = (key) => {
    this.setState({
      currentPanelState: key
    }, () => {
      // const { activePanels } = this.state
      // let data = { ...activePanels }

      // if (!this.state.nextButtonEnabled) {
      //   key.forEach(item => {
      //     let accordianNumber = Number(item)
      //     if (!data.hasOwnProperty(accordianNumber)) {
      //       data[accordianNumber] = true
      //     }
      //   })
      //   this.setState({
      //     activePanels: data
      //   })
      //   if (size(data) === 5) {
      //     this.setState({
      //       nextButtonEnabled: true
      //     })
      //   }
      // }
      // }
    })
  }

  disabledNextButton = (type = '') => {
    this.setState({
      nextButtonEnabled: type === 'true'
    })
  }

  setFormFieldsDataValues = async (object) => {
    const { packageData, step1Data } = this.state
    const newLocalStorage = setFormFieldsDataFunction(object, this) || {}
    const data = payloadFormationFunction(newLocalStorage, step1Data)
    const payload = data
    delete payload.code
    const URLS = payload.policy_creation_wording_urls
    const endorsementURL = payload.policy_endorsement_wording_urls
    payload.policy_creation_wording_urls = Array.isArray(URLS) ? URLS.join(',') : URLS
    payload.policy_endorsement_wording_urls = Array.isArray(endorsementURL) ? endorsementURL.join(',') : endorsementURL

    if (data.formula_expression && data.use_formula === 1) {
      const evaluateSuccess = await new Promise((resolve) => {
        this.props.evaluateFormulaRequest({
          expression: data.formula_expression,
          productCode: get(step1Data, 'code'),
          packageCode: get(packageData, 'code'),
          onSuccess: () => resolve(true),
          onError: () => resolve(false)
        })
      })
      if (!evaluateSuccess) {
        notification.error(
          { message: "Invalid expression" }
        )
        return;
      }
    }

    this.props.editPackage({
      query: {
        productCode: get(step1Data, 'code'),
        packageCode: get(packageData, 'code')
      },
      body: payload
    })
  }

  handleOnSubmitEdit = (e) => {
    e.preventDefault()
    const { form } = this.props
    const { setFieldsValue, getFieldsValue } = form
    const data = getFieldsValue()

    if (data?.coverage_end_static_datetime) {
      const newDate = moment(data?.coverage_end_static_datetime)?.format('YYYY-MM-DD HH:MM:SS')
      setFieldsValue({
        coverage_end_static_datetime: newDate
      })
    }
    if (data?.endorsement_coverage_end_static_datetime) {
      const newDate = moment(data?.coverage_end_static_datetime)?.format('YYYY-MM-DD HH:MM:SS')
      setFieldsValue({
        endorsement_coverage_end_static_datetime: newDate
      })
    }
    this.props.form.validateFields(async (err, values) => {
      if (!err) {
        const formBodyData = form.getFieldsValue()
        await this.setFormFieldsDataValues(formBodyData)
      } else {
        this.setState({
          currentPanelState: [errorSectionCheck(err)]
        })
      }
    })
  }

  handleGoBack = () => {
    this.props.history.goBack()
  }

  componentWillUnmount () {
    removeLocalStorage(['formData', 'provider', 'timezone', 'countriesData', 'new_premium_logic', 'configList'])
  }

  render () {
    const { editPackageLoading, editPackageError } = this.props
    const { currentPanelState, nextButtonEnabled, packageData, step1Data, step2Data } = this.state
    const code = get(packageData, 'code')
    return (
      <Spin spinning={editPackageLoading && !editPackageError} tip='Edit Package Page Loading ...'>
        <EditPackageStyleWrapper>
          <PageHeadWrapper
            heading={`Edit Package Info - ${code}`}
          >
            <Form onSubmit={this.handleOnSubmitEdit}>
              <Row type='flex' justify='center' gutter={40}>
                <Col span={20}>
                  <CollapseWrapper
                    history={this.props.history}
                    form={this.props.form}
                    currentPanelState={currentPanelState}
                    onChangePanel={this.handleChangePanel}
                    nextButtonEnabledFunction={this.disabledNextButton}
                    packageData={packageData}
                    editForm
                    step1Data={step1Data}
                    step2Data={step2Data}
                  />
                </Col>
              </Row>
              <Row type='flex' justify='center'>
                <Col span={4}>
                  <div className='button-div'>
                    <Button onClick={this.handleGoBack}>Cancel</Button>
                    <Button type='primary' disabled={!nextButtonEnabled} htmlType='submit'> Submit </Button>
                  </div>
                </Col>
              </Row>
            </Form>
          </PageHeadWrapper>
        </EditPackageStyleWrapper>
      </Spin>
    )
  }
}
EditPackage.defaultProps = {
  editPackageError: false,
  editPackageLoading: false
}
EditPackage.propTypes = {
  editPackageError: PropTypes.bool,
  editPackageLoading: PropTypes.bool
}
const WrappedEditPackage = Form.create()(EditPackage)

export default connect(
  state => ({
    editPackageData: state.ProductConfigurable.editPackageData,
    editPackageMessage: state.ProductConfigurable.editPackageMessage,
    editPackageLoading: state.Loading.EDIT_PACKAGE,
    editPackageError: state.Error.EDIT_PACKAGE
  }), {
    resetProductConfigRedux,
    editPackage,
    evaluateFormulaRequest: policyActions.evaluateFormula,
  }
)(WrappedEditPackage)
